%dw 2.0
output application/json
var mappedProducts=payload.productDetails map (prod) -> do{
		var cartData = (payload.cart filter($.productId == prod.productId))[0]
		---
		(prod - ("storeId")) ++ {inCartQuantity:cartData.quantity}
	}
---
{
	productCount:sizeOf(payload.cart),
	totalItems:sum(payload.cart.quantity),
	products:mappedProducts,
	totalCartValue: sum(mappedProducts map($.inCartQuantity*$.price))
}

